examples.template:
MonarchFileCard(
    name = {{name}},
    modifier = Modifier.width(MonarchTheme.spacing.space24 * 3),
    sizeBytes = {{size}},
    selected = selected,
    onSelectedChange = { selected = it },
    onOpen = {},
) {
    Box {
        MonarchIconButton(label = "Actions for " + {{name}}, onClick = { menu = true }) {
            MonarchIcon(SampleIcons.More, contentDescription = null)
        }
        MonarchMenu(expanded = menu, onDismissRequest = { menu = false }) {
            MonarchMenuItem(text = {{menu.0}}, onClick = { menu = false })
            MonarchMenuItem(text = {{menu.1}}, onClick = { menu = false })
            MonarchMenuItem(text = {{menu.2}}, onClick = { menu = false }, destructive = true)
        }
    }
}

